import React, { useEffect, useState } from 'react';
import { InvoiceLineItems } from './InvoiceLineItems';
import { InvoicePayments } from './InvoicePayments';

// A project's invoices, rendered inside the projects feature when a project is opened. Lists the
// project's invoices, shows their derived total (amounts to 2 decimals), and adds a new invoice by
// amount. Each invoice's status is worked out from the payments recorded against it — PARTIAL once
// some is paid, PAID once covered — rather than being flipped to paid by hand. Opening an invoice
// (invoice-open-<id>) shows its derived status, its line items — the things being charged for — and
// its payments in place of the list. Owns its own state and data loading (no global store);
// composed, not branched.
type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  due: number;
  status: string;
  issuedDate: string | null;
  dueDate: string | null;
  discountPct: number;
};

function formatAmount(amount: number): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function ProjectInvoices({ projectId }: { projectId: number }) {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [amount, setAmount] = useState('');
  const [error, setError] = useState('');
  const [sort, setSort] = useState<'id' | 'due'>('id');
  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
  const [openStatus, setOpenStatus] = useState('');
  const [openDiscountPct, setOpenDiscountPct] = useState(0);

  async function load(order: 'id' | 'due' = sort) {
    const res = await fetch(`/api/projects/${projectId}/invoices?sort=${order}`);
    setInvoices(await res.json());
  }

  // The opened invoice's status is derived from its payments, so re-read it on open and whenever a
  // payment is recorded against it.
  async function loadInvoice(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}`);
    if (!res.ok) {
      return;
    }
    const inv: Invoice = await res.json();
    setOpenStatus(inv.status);
    setOpenDiscountPct(Number(inv.discountPct ?? 0));
  }

  useEffect(() => {
    void load();
  }, [projectId]);

  useEffect(() => {
    if (openInvoiceId !== null) {
      void loadInvoice(openInvoiceId);
    }
  }, [openInvoiceId]);

  async function sortByDue() {
    setSort('due');
    await load('due');
  }

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const value = Number(amount);
    if (!(value > 0)) {
      setError('Amount must be greater than zero');
      return;
    }
    setError('');
    const res = await fetch(`/api/projects/${projectId}/invoices`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount: Number(amount) }),
    });
    if (!res.ok) {
      return;
    }
    setAmount('');
    await load();
  }

  async function send(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/send`, { method: 'POST' });
    if (!res.ok) {
      return;
    }
    await load();
  }

  // Cancel (void) an invoice sent by mistake: it reads VOID and stops counting toward what is owed.
  async function cancel(invoiceId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/void`, { method: 'POST' });
    if (!res.ok) {
      return;
    }
    await load();
  }

  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);

  if (openInvoiceId !== null) {
    return (
      <section data-testid="project-invoices">
        <h2>Invoices</h2>
        <p>
          Status: <span data-testid="invoice-status">{openStatus}</span>
        </p>
        <InvoiceLineItems
          invoiceId={openInvoiceId}
          discountPct={openDiscountPct}
          onClose={() => {
            setOpenInvoiceId(null);
            void load();
          }}
        />
        <InvoicePayments
          invoiceId={openInvoiceId}
          onRecorded={() => void loadInvoice(openInvoiceId)}
        />
      </section>
    );
  }

  return (
    <section data-testid="project-invoices">
      <h2>Invoices</h2>

      <form data-testid="invoice-form" onSubmit={onSubmit}>
        <input
          data-testid="invoice-form-amount"
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
        />
        <button type="submit" data-testid="invoice-form-submit">
          Add invoice
        </button>
        {error ? (
          <p data-testid="invoice-form-amount-error" role="alert">
            {error}
          </p>
        ) : null}
      </form>

      <button type="button" data-testid="invoice-sort-due" onClick={() => void sortByDue()}>
        Sort by due date
      </button>

      <table data-testid="project-invoices-table">
        <thead>
          <tr>
            <th>Amount</th>
            <th>Due</th>
            <th>Status</th>
            <th>Issued</th>
            <th>Due</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {invoices.map((inv) => (
            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
              <td data-testid="invoice-amount">{formatAmount(inv.amount)}</td>
              <td data-testid="invoice-due-amount">{formatAmount(inv.due)}</td>
              <td data-testid="invoice-status">{inv.status}</td>
              <td data-testid="invoice-issued">{inv.issuedDate ?? ''}</td>
              <td data-testid="invoice-due">{inv.dueDate ?? ''}</td>
              <td>
                <button
                  type="button"
                  data-testid={`invoice-open-${inv.id}`}
                  onClick={() => setOpenInvoiceId(inv.id)}
                >
                  Open
                </button>
                {inv.status === 'DRAFT' ? (
                  <button
                    type="button"
                    data-testid={`invoice-send-${inv.id}`}
                    onClick={() => void send(inv.id)}
                  >
                    Send
                  </button>
                ) : null}
                {inv.status === 'SENT' ? (
                  <button
                    type="button"
                    data-testid={`invoice-cancel-${inv.id}`}
                    onClick={() => void cancel(inv.id)}
                  >
                    Cancel
                  </button>
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td data-testid="project-invoices-total">{formatAmount(total)}</td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}
===INVOICE LINE ITEMS===
import React, { useEffect, useState } from 'react';

// An opened invoice's line items, rendered inside the projects feature. The owner lists the things
// being charged for — each with a description, how many, the unit that quantity is measured in, and
// the price each — and the amount for each line (and the invoice total) is worked out for them (the
// sum of each line's quantity times unit price). Owns its own state and data loading (no global
// store); composed, not branched.
type LineItem = {
  id: number;
  invoiceId: number;
  description: string;
  quantity: number;
  unit: string;
  unitPrice: number;
};

function formatAmount(amount: number): string {
  return `$${Number(amount).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

export function InvoiceLineItems({
  invoiceId,
  discountPct = 0,
  onClose,
}: {
  invoiceId: number;
  discountPct?: number;
  onClose: () => void;
}) {
  const [lineItems, setLineItems] = useState<LineItem[]>([]);
  const [description, setDescription] = useState('');
  const [qty, setQty] = useState('');
  const [unit, setUnit] = useState('');
  const [unitPrice, setUnitPrice] = useState('');
  const [error, setError] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDescription, setEditDescription] = useState('');
  const [editQty, setEditQty] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editUnitPrice, setEditUnitPrice] = useState('');
  const [editError, setEditError] = useState('');

  async function load() {
    const res = await fetch(`/api/invoices/${invoiceId}/lineitems`);
    setLineItems(await res.json());
  }

  useEffect(() => {
    void load();
  }, [invoiceId]);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    const quantity = Number(qty);
    const price = Number(unitPrice);
    if (!description.trim() || !(quantity > 0) || !(price >= 0)) {
      setError('A description, a quantity and a price are required');
      return;
    }
    setError('');
    const res = await fetch(`/api/invoices/${invoiceId}/lineitems`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ description, quantity, unit, unitPrice: price }),
    });
    if (!res.ok) {
      return;
    }
    setDescription('');
    setQty('');
    setUnit('');
    setUnitPrice('');
    await load();
  }

  function startEdit(li: LineItem) {
    setEditingId(li.id);
    setEditDescription(li.description);
    setEditQty(String(li.quantity));
    setEditUnit(li.unit);
    setEditUnitPrice(String(li.unitPrice));
    setEditError('');
  }

  function cancelEdit() {
    setEditingId(null);
    setEditError('');
  }

  async function saveEdit(lineItemId: number) {
    const quantity = Number(editQty);
    const price = Number(editUnitPrice);
    if (!editDescription.trim() || !(quantity > 0) || !(price >= 0)) {
      setEditError('A description, a quantity and a price are required');
      return;
    }
    setEditError('');
    const res = await fetch(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ description: editDescription, quantity, unit: editUnit, unitPrice: price }),
    });
    if (!res.ok) {
      return;
    }
    setEditingId(null);
    await load();
  }

  async function remove(lineItemId: number) {
    const res = await fetch(`/api/invoices/${invoiceId}/lineitems/${lineItemId}`, {
      method: 'DELETE',
    });
    if (!res.ok) {
      return;
    }
    if (editingId === lineItemId) {
      setEditingId(null);
    }
    await load();
  }

  // The subtotal is the sum of the line items; the owner can take a percentage off it as a discount,
  // and the invoice's final total is what is left after that discount.
  const subtotal = lineItems.reduce(
    (sum, li) => sum + Number(li.quantity) * Number(li.unitPrice),
    0,
  );
  const discount = subtotal * (Number(discountPct) / 100);
  const total = subtotal - discount;

  return (
    <section data-testid="invoice-lineitems">
      <h2>Invoice line items</h2>

      <button type="button" data-testid="invoice-close" onClick={onClose}>
        Back to invoices
      </button>

      <form data-testid="lineitem-form" onSubmit={onSubmit}>
        <input
          data-testid="lineitem-form-description"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <input
          data-testid="lineitem-form-qty"
          placeholder="How many"
          value={qty}
          onChange={(e) => setQty(e.target.value)}
        />
        <input
          data-testid="lineitem-form-unit"
          placeholder="Unit"
          value={unit}
          onChange={(e) => setUnit(e.target.value)}
        />
        <input
          data-testid="lineitem-form-unitprice"
          placeholder="Price each"
          value={unitPrice}
          onChange={(e) => setUnitPrice(e.target.value)}
        />
        <button type="submit" data-testid="lineitem-form-submit">
          Add line item
        </button>
        {error ? (
          <p data-testid="lineitem-form-error" role="alert">
            {error}
          </p>
        ) : null}
      </form>

      <table data-testid="invoice-lineitems-table">
        <thead>
          <tr>
            <th>Description</th>
            <th>How many</th>
            <th>Unit</th>
            <th>Price each</th>
            <th>Amount</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {lineItems.map((li) =>
            editingId === li.id ? (
              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
                <td>
                  <input
                    data-testid="lineitem-edit-description"
                    placeholder="Description"
                    value={editDescription}
                    onChange={(e) => setEditDescription(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid="lineitem-edit-qty"
                    placeholder="How many"
                    value={editQty}
                    onChange={(e) => setEditQty(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid="lineitem-edit-unit"
                    placeholder="Unit"
                    value={editUnit}
                    onChange={(e) => setEditUnit(e.target.value)}
                  />
                </td>
                <td>
                  <input
                    data-testid="lineitem-edit-unitprice"
                    placeholder="Price each"
                    value={editUnitPrice}
                    onChange={(e) => setEditUnitPrice(e.target.value)}
                  />
                </td>
                <td data-testid="lineitem-total">
                  <span data-testid="lineitem-amount">
                    {formatAmount(Number(editQty || 0) * Number(editUnitPrice || 0))}
                  </span>
                </td>
                <td>
                  <button
                    type="button"
                    data-testid={`lineitem-save-${li.id}`}
                    onClick={() => void saveEdit(li.id)}
                  >
                    Save
                  </button>
                  <button
                    type="button"
                    data-testid={`lineitem-cancel-${li.id}`}
                    onClick={cancelEdit}
                  >
                    Cancel
                  </button>
                  {editError ? (
                    <p data-testid="lineitem-edit-error" role="alert">
                      {editError}
                    </p>
                  ) : null}
                </td>
              </tr>
            ) : (
              <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
                <td data-testid="lineitem-description">{li.description}</td>
                <td data-testid="lineitem-qty">{li.quantity}</td>
                <td data-testid="lineitem-unit">{li.unit}</td>
                <td data-testid="lineitem-unitprice">{formatAmount(li.unitPrice)}</td>
                <td data-testid="lineitem-total">
                  <span data-testid="lineitem-amount">
                    {formatAmount(Number(li.quantity) * Number(li.unitPrice))}
                  </span>
                </td>
                <td>
                  <button
                    type="button"
                    data-testid={`lineitem-edit-${li.id}`}
                    onClick={() => startEdit(li)}
                  >
                    Change
                  </button>
                  <button
                    type="button"
                    data-testid={`lineitem-remove-${li.id}`}
                    onClick={() => void remove(li.id)}
                  >
                    Remove
                  </button>
                </td>
              </tr>
            ),
          )}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={4}>Subtotal</td>
            <td data-testid="invoice-subtotal">{formatAmount(subtotal)}</td>
            <td></td>
          </tr>
          <tr>
            <td colSpan={4}>Discount ({Number(discountPct)}%)</td>
            <td data-testid="invoice-discount">{formatAmount(discount)}</td>
            <td></td>
          </tr>
          <tr>
            <td colSpan={4}>Total</td>
            <td data-testid="invoice-amount">{formatAmount(total)}</td>
            <td></td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}

