package net.officefloor.hq.app;

import java.math.BigDecimal;
import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/invoices/{invoiceId} — a single invoice as the UI shows it, including how much is still
 * owing ({@code due}) and its payment status derived from the payments recorded against it. An
 * unknown invoice is rejected with 400. Used by an opened invoice to show its current status.
 */
public class GetInvoiceLogic {

    public void service(@HttpPathParameter("invoiceId") String invoiceId,
            InvoiceRepository invoices, PaymentRepository payments,
            ObjectResponse<InvoiceView> response) {
        Long id = Long.valueOf(invoiceId);
        Invoice inv = invoices.findById(id).orElseThrow(
                () -> new HttpException(HttpStatus.BAD_REQUEST, "An existing invoice is required"));
        BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(id).stream()
                .map(Payment::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal due = inv.getAmount().subtract(paid);
        String status = InvoiceStatus.derive(inv.getStatus(), inv.getAmount(), paid);
        response.send(new InvoiceView(inv.getId(), inv.getProjectId(), inv.getAmount(), due, status,
                inv.getIssuedDate() == null ? null : inv.getIssuedDate().toString(),
                inv.getDueDate() == null ? null : inv.getDueDate().toString(), inv.getDiscountPct()));
    }
}
=== ListInvoicesLogic.java ===
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;
import net.officefloor.web.HttpPathParameter;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/projects/{projectId}/invoices — a project's invoices. Ordered oldest first by default;
 * {@code ?sort=due} orders them by their due date, earliest first (id as a stable tie-breaker).
 */
public class ListInvoicesLogic {

    public void service(@HttpPathParameter("projectId") String projectId,
            @HttpQueryParameter("sort") String sort, InvoiceRepository invoices,
            PaymentRepository payments, ObjectResponse<List<InvoiceView>> response) {
        Long id = Long.valueOf(projectId);
        List<Invoice> ordered = "due".equals(sort)
                ? invoices.findByProjectIdOrderByDueDateAscIdAsc(id)
                : invoices.findByProjectIdOrderByIdAsc(id);
        List<InvoiceView> views = ordered.stream()
                .map(inv -> {
                    // What is still left to pay: the billed amount minus everything paid so far.
                    BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(inv.getId()).stream()
                            .map(Payment::getAmount)
                            .reduce(BigDecimal.ZERO, BigDecimal::add);
                    BigDecimal due = inv.getAmount().subtract(paid);
                    // Status follows the payments: PAID once covered, PARTIAL once some is paid.
                    String status = InvoiceStatus.derive(inv.getStatus(), inv.getAmount(), paid);
                    return new InvoiceView(inv.getId(), inv.getProjectId(), inv.getAmount(), due,
                            status,
                            inv.getIssuedDate() == null ? null : inv.getIssuedDate().toString(),
                            inv.getDueDate() == null ? null : inv.getDueDate().toString());
                })
                .collect(Collectors.toList());
        response.send(views);
    }
}
=== V30 ===
-- An invoice may carry a percentage discount the owner takes off the subtotal (the sum of its line
-- items). The invoice detail shows the subtotal, the discount amount (subtotal times the percentage)
-- and the final total (subtotal minus the discount). Existing invoices have no discount, so default
-- to 0; the stored invoice.amount column keeps meaning the undiscounted subtotal of its line items.
ALTER TABLE invoice ADD COLUMN discount_pct INT NOT NULL DEFAULT 0;
=== V4 ===
-- Invoices: the owner bills work against a project. Each invoice belongs to one project
-- (project_id references project.id) and carries a monetary amount. Third domain table; a project's
-- detail screen lists its invoices and shows their total.
CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT NOT NULL REFERENCES project(id),
    amount     DECIMAL(12, 2) NOT NULL
);

